TreeNode* buildTree(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> pending;
    pending.push(root);
    size_t i = 1;
    while (!pending.empty() && i < tokens.size()) {
        TreeNode* node = pending.front();
        pending.pop();
        if (i < tokens.size() && tokens[i] != "null") { node->left = new TreeNode(stoi(tokens[i])); pending.push(node->left); }
        i++;
        if (i < tokens.size() && tokens[i] != "null") { node->right = new TreeNode(stoi(tokens[i])); pending.push(node->right); }
        i++;
    }
    return root;
}

